"""Five design-approved exceptions; not a coverage dictionary (§5.3).

The source list lives here. Generated runtime TSV must not be edited by hand.
Independent linguistic review remains pending; no entries are added by matching
the engine output to a test reference.
"""
WORDS = (("音樂", "음악"), ("男女老少", "남녀노소"), ("金氏", "김씨"),
         ("ソウル", "서울"), ("うどん", "우동"))


def build(out):
    header = (
        "# Generated by tools/cjk/word_table.py; do not edit by hand.\n"
        "# Minimum system word list. Every entry exists because character fallback plus\n"
        "# the run-initial rule provably cannot produce the authored contract; see\n"
        "# tests/evaluation/cjk_reading_v22.jsonl (basis: word-entry) and the\n"
        "# simulation in tools/cjk/. Do not grow this file to raise coverage:\n"
        "# design 1 makes readability, not coverage, the success criterion.\n"
        "# Review status is pending independent linguistic review in every row.\n"
    )
    out.mkdir(parents=True, exist_ok=True)
    (out / "cjk_words.tsv").write_text(header + "".join(
        f"cjk_word\tko-KR\t{key}\t{value}\n" for key, value in WORDS),
        encoding="utf-8", newline="\n")
    return dict(rows=len(WORDS), review_status="pending-independent-review")
